WITH filtered AS (SELECT id, customer_id, browser, started_at, country, CASE WHEN device IN ('tablet', 'desktop') THEN 'Group A' ELSE 'Other' END AS device_group, LOWER(country) AS country_lower FROM sessions WHERE country IS NOT NULL AND browser IS DISTINCT FROM 'Firefox') SELECT id, browser, started_at, country, device_group FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY browser, customer_id ORDER BY started_at, id) = 1
